import React from 'react';
import { isElement } from 'react-is';

import { ColumnOrder } from './components/ColumnOrder.js';
import { FontStyle } from './components/FontStyle.js';
import { HideColumn } from './components/HideColumn.js';
import { LineWrap } from './components/LineWrap.js';
import { TableUserActions } from './components/TableUserActions.js';

/** Actions provided by the plugin to trigger state updates. */
export const useUserActionsActions = {
  /** Action fired internally when the props of a column have been changed. */
  columnPropertiesChanged: 'Column properties changed',
};

/**
 * Separates a `TableUserActions` object containing column actions into
 * default action items and custom action items.
 *
 * @param tableUserActions - An instance of `TableUserActions`.
 */
export const separateColumnActions = (
  tableUserActions: React.ReactElement | null,
  hasSubHeaders: boolean,
) => {
  const actions: {
    defaultActions: React.ReactElement[];
    customActions: React.ReactElement[];
  } = {
    defaultActions: [],
    customActions: [],
  };

  if (
    !isElement(tableUserActions) ||
    tableUserActions.type !== TableUserActions
  ) {
    return actions;
  }

  React.Children.forEach(tableUserActions.props.children, (child) => {
    if (!isElement(child)) {
      return;
    }

    switch (child.type) {
      case LineWrap:
        if (!hasSubHeaders) {
          actions.defaultActions.push(child);
        }
        break;
      case HideColumn:
        actions.defaultActions.push(child);
        break;
      case ColumnOrder:
        actions.defaultActions.push(child);
        break;
      case FontStyle:
        actions.defaultActions.push(child);
        break;
      default:
        actions.customActions.push(child);
        break;
    }
  });

  return actions;
};
